1: // small control plane: CLI API + browser auth wall + router. One Worker + D1.
2: // URLs are path-based (no custom domain): /a/<org>/<app>/... proxies to the app's Fly origin.
3: import { sign, verify, sha256, randomHex } from './token.js';
4: import { ensureFlyApp, ensureVolume, deployTokenFor, startMachine } from './fly.js';
5: import { assumeRole } from './aws.js';
6: import { runReview } from './review.js';
