11: const orgOf = (email) => email.split('@')[1].toLowerCase().replace(/\./g, '-');
12: const now = () => Math.floor(Date.now() / 1000);
13: const json = (data, status = 200) => new Response(JSON.stringify(data), { status, headers: { 'Content-Type': 'application/json' } });
