20: async function sendEmail(env, to, subject, text) {
21:   if (!env.RESEND_API_KEY) return false; // dev mode: caller falls back to echoing the code/link
22:   const resp = await fetch('https://api.resend.com/emails', {
23:     method: 'POST',
24:     headers: { Authorization: `Bearer ${env.RESEND_API_KEY}`, 'Content-Type': 'application/json' },
25:     body: JSON.stringify({ from: env.EMAIL_FROM || 'small <[REDACTED]>', to: [to], subject, text }),
26:   });
27:   return resp.ok;
28: }
