48: async function canView(env, app, email) {
49:   if (app.owner_email === email) return true;
50:   const member = await env.DB.prepare('SELECT role FROM members WHERE app_id = ? AND email = ?').bind(app.id, email).first();
51:   if (member) return true;
52:   return app.visibility === 'domain' && orgOf(email) === app.org;
53: }
