84: async function apiDeploy(req, env, ctx, user, baseUrl) {
85:   const { name, framework, visibility, awsRoleArn, kind, review, storage } = await req.json();
86:   if (!name || !/^[a-z0-9-]{1,40}$/.test(name)) return json({ error: 'name must be [a-z0-9-]' }, 400);
87:   if (storage && !(Number.isInteger(storage.sizeGb) && storage.sizeGb >= 1 && storage.sizeGb <= 100))
88:     return json({ error: 'storage.sizeGb must be an integer between 1 and 100' }, 400);
89:   if (awsRoleArn && !/^arn:aws:iam::\d{12}:role\/[\w+=,.@/-]+$/.test(awsRoleArn)) return json({ error: 'bad aws role arn' }, 400);
90:   let app = await appRow(env, user.org, name);
91:   if (app) {
92:     if (!(await canEdit(env, app, user.email))) return json({ error: `${name} exists and you cannot edit it` }, 403);
93:     if (visibility) await env.DB.prepare('UPDATE apps SET visibility = ? WHERE id = ?').bind(visibility, app.id).run();
94:     if (awsRoleArn !== undefined) await env.DB.prepare('UPDATE apps SET aws_role_arn = ? WHERE id = ?').bind(awsRoleArn || null, app.id).run();
95:     if (kind) await env.DB.prepare('UPDATE apps SET kind = ? WHERE id = ?').bind(kind === 'job' ? 'job' : 'server', app.id).run();
96:   } else {
97:     const flyApp = `small-${name}-${randomHex(3)}`;
98:     await env.DB.prepare('INSERT INTO apps (org, name, fly_app, proxy_secret, visibility, owner_email, aws_role_arn, kind) VALUES (?, ?, ?, ?, ?, ?, ?, ?)')
99:       .bind(user.org, name, flyApp, randomHex(32), visibility || 'domain', user.email, awsRoleArn || null, kind === 'job' ? 'job' : 'server')
100:       .run();
101:     app = await appRow(env, user.org, name);
102:   }
103:   if (!env.FLY_API_TOKEN) return json({ error: 'control plane has no FLY_API_TOKEN configured' }, 503);
104:   // The worker owns the Fly app lifecycle; the CLI only gets a 1h token scoped to this one app.
105:   let flyToken, volumeRegion;
106:   try {
107:     await ensureFlyApp(env, app.fly_app);
108:     if (storage) volumeRegion = await ensureVolume(env, app.fly_app, storage.sizeGb);
109:     flyToken = await deployTokenFor(env, app);
110:   } catch (e) {
111:     return json({ error: e.message }, 502);
112:   }
113:   // Review runs concurrently with the CLI-side Fly build; it never blocks or fails the deploy.
114:   const reviewStarted = !!(env.ANTHROPIC_API_KEY && review && review.bundle);
115:   if (reviewStarted) ctx.waitUntil(runReview(env, app.id, review.bundle, review.skipped || []));
116:   return json({
117:     flyApp: app.fly_app,
118:     proxySecret: app.proxy_secret,
119:     flyToken,
120:     url: `${baseUrl}/a/${user.org}/${name}/`,
121:     framework: framework || null,
122:     volumeRegion: volumeRegion || null,
123:     reviewStarted,
124:     reviewedAt: app.reviewed_at || null, // previous review's stamp; the CLI polls until it changes
125:   });
126: }
