128: async function apiReview(req, env, user) {
129:   const name = new URL(req.url).searchParams.get('app');
130:   const app = await appRow(env, user.org, name);
131:   if (!app) return json({ error: `no app named ${name}` }, 404);
132:   if (!(await canView(env, app, user.email))) return json({ error: 'no access' }, 403);
133:   return json({
