141: async function apiShare(req, env, user) {
142:   const { app: name, email, role } = await req.json();
143:   const app = await appRow(env, user.org, name);
144:   if (!app) return json({ error: `no app named ${name}` }, 404);
145:   if (!(await canEdit(env, app, user.email))) return json({ error: 'only owner or edit members can share' }, 403);
146:   await env.DB.prepare('INSERT INTO members (app_id, email, role) VALUES (?, ?, ?) ON CONFLICT(app_id, email) DO UPDATE SET role = excluded.role')
147:     .bind(app.id, email.toLowerCase(), role === 'edit' ? 'edit' : 'view')
148:     .run();
149:   return json({ ok: true, app: name, email: email.toLowerCase(), role: role === 'edit' ? 'edit' : 'view' });
150: }
