208: // Runtime endpoint: the guard inside a machine trades its proxy secret for 1h STS
209: // session creds scoped by the customer's role. No CLI token involved — the proxy
210: // secret is per-app and high-entropy. ExternalId pins the role to the app's org so
211: // one org cannot point small.toml at another org's role (confused deputy).
212: async function apiAwsCreds(req, env) {
213:   const { secret } = await req.json();
214:   if (!secret) return json({ error: 'secret required' }, 400);
215:   const app = await env.DB.prepare('SELECT * FROM apps WHERE proxy_secret = ?').bind(secret).first();
216:   if (!app) return json({ error: 'forbidden' }, 403);
217:   if (!app.aws_role_arn) return json({ error: 'no aws role configured for this app' }, 404);
218:   if (!env.AWS_ACCESS_KEY_ID || !env.AWS_SECRET_ACCESS_KEY) return json({ error: 'control plane has no AWS principal configured' }, 503);
219:   try {
220:     return json(await assumeRole(env, app.aws_role_arn, `small-${app.org}-${app.name}`, app.org));
221:   } catch (e) {
222:     return json({ error: e.message }, 502);
223:   }
224: }
