239: async function apiRunStart(req, env, user, baseUrl) {
240:   const { app: name } = await req.json();
241:   const app = await appRow(env, user.org, name);
242:   if (!app) return json({ error: `no app named ${name}` }, 404);
243:   if (!(await canView(env, app, user.email))) return json({ error: 'no access' }, 403);
244:   if (app.kind !== 'job') return json({ error: `${name} is not a job — set kind = "job" in small.toml and redeploy` }, 400);
245:   if (!app.image) return json({ error: `no image for ${name} — run small deploy first` }, 409);
246:   if (!env.FLY_ORG_TOKEN && !env.FLY_API_TOKEN) return json({ error: 'control plane has no fly token configured' }, 503);
247:   const runId = 'r-' + randomHex(6);
248:   await env.DB.prepare('INSERT INTO runs (run_id, app_id, started_by) VALUES (?, ?, ?)').bind(runId, app.id, user.email).run();
249:   const runToken = await sign({ t: 'run', run: runId, exp: now() + 6 * 3600 }, env.MASTER_KEY);
250:   try {
251:     await startMachine(env, app.fly_app, {
252:       image: app.image,
253:       auto_destroy: true,
254:       restart: { policy: 'no' },
255:       guest: { cpu_kind: 'shared', cpus: 1, memory_mb: 256 }, // ponytail: fixed size; read memory from small.toml when a job needs more
256:       env: { SMALL_RUN_ID: runId, SMALL_RUN_TOKEN: runToken, SMALL_USER: user.email, SMALL_API: baseUrl },
257:     });
258:   } catch (e) {
259:     await env.DB.prepare("UPDATE runs SET status = 'failed', finished_at = datetime('now') WHERE run_id = ?").bind(runId).run();
260:     return json({ error: e.message }, 502);
261:   }
262:   return json({ runId });
263: }
