276: async function apiRunGet(req, env, user, runId) {
277:   const run = await env.DB.prepare(
278:     'SELECT runs.status, runs.exit_code, apps.id AS app_id, apps.org, apps.owner_email, apps.visibility FROM runs JOIN apps ON apps.id = runs.app_id WHERE runs.run_id = ?'
279:   ).bind(runId).first();
280:   if (!run || run.org !== user.org) return json({ error: `no run ${runId}` }, 404);
281:   if (!(await canView(env, { id: run.app_id, org: run.org, owner_email: run.owner_email, visibility: run.visibility }, user.email)))
282:     return json({ error: 'no access' }, 403);
283:   const after = Number(new URL(req.url).searchParams.get('after') ?? -1);
284:   const { results } = await env.DB.prepare('SELECT seq, line FROM run_logs WHERE run_id = ? AND seq > ? ORDER BY seq').bind(runId, after).all();
285:   return json({
286:     status: run.status,
287:     exitCode: run.exit_code,
288:     lines: results.map((r) => r.line),
289:     cursor: results.length ? results[results.length - 1].seq : after,
290:   });
291: }
