337: async function authRedirect(req, env) {
338:   const token = new URL(req.url).searchParams.get('token');
339:   const p = await verify(token, env.MASTER_KEY);
340:   if (!p || p.t !== 'magic') return html('<p>Link expired or invalid. <a href="/login">Try again</a>.</p>', 401);
341:   const sess = await sign({ t: 'sess', email: p.email, exp: now() + SESSION_TTL }, env.MASTER_KEY);
342:   return new Response(null, { status: 302, headers: { Location: p.next || '/', 'Set-Cookie': sessionCookie(sess) } });
343: }
