345: // Test bypass: mint a session without email. Enabled only when TEST_BYPASS_SECRET is set.
346: async function testSession(req, env) {
347:   if (!env.TEST_BYPASS_SECRET) return json({ error: 'not enabled' }, 404);
348:   const { email, secret } = await req.json();
349:   if (secret !== env.TEST_BYPASS_SECRET) return json({ error: 'bad secret' }, 401);
350:   const sess = await sign({ t: 'sess', email: email.toLowerCase(), exp: now() + SESSION_TTL }, env.MASTER_KEY);
351:   return json({ session: sess }, 200);
352: }
