354: // ---------- Router/proxy ----------
355: 
356: async function proxyApp(req, env, org, name, rest, baseUrl) {
357:   const sess = await sessionOf(req, env);
358:   const prefix = `/a/${org}/${name}`;
359:   if (!sess) {
360:     if (req.method !== 'GET') return json({ error: 'login required' }, 401);
361:     return new Response(null, { status: 302, headers: { Location: `${baseUrl}/login?next=${encodeURIComponent(prefix + '/')}` } });
362:   }
363:   const app = await appRow(env, org, name);
364:   if (!app) return html(`<p>No app <b>${name}</b> here.</p>`, 404);
365:   if (!(await canView(env, app, sess.email))) return html(`<p><b>${sess.email}</b> does not have access to <b>${name}</b>. Ask the owner to run <code>small share ${sess.email}</code>.</p>`, 403);
366:   if (rest === '') return new Response(null, { status: 301, headers: { Location: `${prefix}/` } }); // relative URLs need the trailing slash
367: 
368:   const origin = `https://${app.fly_app}.fly.dev`;
369:   const target = new URL(req.url);
370:   const headers = new Headers(req.headers);
371:   headers.delete('Cookie'); // the app never sees the session
372:   headers.delete('X-Small-Session');
373:   headers.set('X-Small-User', sess.email);
374:   headers.set('X-Small-Org', org);
375:   headers.set('X-Small-Proxy', app.proxy_secret);
376:   let resp;
377:   for (let attempt = 0; ; attempt++) {
378:     resp = await fetch(`${origin}${rest}${target.search}`, {
379:       method: req.method,
380:       headers,
381:       body: ['GET', 'HEAD'].includes(req.method) ? undefined : req.body,
382:       redirect: 'manual',
383:     });
384:     // Fly answers 502/503 while a scaled-to-zero machine wakes (~30s for torch-heavy apps);
385:     // hold safe-to-repeat requests instead of showing the browser a Bad Gateway.
386:     if (![502, 503].includes(resp.status) || !['GET', 'HEAD'].includes(req.method) || attempt >= 9) break;
387:     await new Promise((r) => setTimeout(r, 5000));
388:   }
389:   const out = new Headers(resp.headers);
390:   const loc = out.get('Location');
391:   if (loc && loc.startsWith('/') && !loc.startsWith('/a/')) out.set('Location', prefix + loc); // path-based hosting: re-prefix app redirects
392:   return new Response(resp.body, { status: resp.status, headers: out });
393: }
394: 
395: export default {
396:   async fetch(req, env, ctx) {
397:     const url = new URL(req.url);
398:     const baseUrl = `${url.protocol}//${url.host}`;
399:     const path = url.pathname;
400:     try {
401:       if (path === '/api/cli/login' && req.method === 'POST') return await apiLogin(req, env);
402:       if (path === '/api/cli/verify' && req.method === 'POST') return await apiVerify(req, env);
403:       if (path === '/api/runtime/aws-creds' && req.method === 'POST') return await apiAwsCreds(req, env);
404:       if (path.startsWith('/api/')) {
405:         const runLog = path.match(/^\/api\/runs\/([\w-]+)\/log$/);
406:         if (runLog && req.method === 'POST') return await apiRunLog(req, env, runLog[1]); // runner auth, not CLI auth
407:         const reqLog = path.match(/^\/api\/apps\/([a-z0-9-]+)\/request-log$/);
408:         if (reqLog && req.method === 'POST') return await apiRequestLogIngest(req, env, reqLog[1]); // guard auth, not CLI auth
409:         const user = await cliAuth(req, env);
410:         if (!user) return json({ error: 'run small login first' }, 401);
411:         if (path === '/api/deploy' && req.method === 'POST') return await apiDeploy(req, env, ctx, user, baseUrl);
412:         if (path === '/api/image' && req.method === 'POST') return await apiImage(req, env, user);
413:         if (path === '/api/runs' && req.method === 'POST') return await apiRunStart(req, env, user, baseUrl);
414:         if (path === '/api/runs' && req.method === 'GET') return await apiRunsList(req, env, user);
415:         const runGet = path.match(/^\/api\/runs\/([\w-]+)$/);
416:         if (runGet && req.method === 'GET') return await apiRunGet(req, env, user, runGet[1]);
417:         if (path === '/api/share' && req.method === 'POST') return await apiShare(req, env, user);
418:         if (path === '/api/apps' && req.method === 'GET') return await apiApps(env, user);
419:         if (path === '/api/logs' && req.method === 'GET') return await apiLogs(req, env, user);
420:         if (path === '/api/request-logs' && req.method === 'GET') return await apiRequestLogs(req, env, user);
421:         if (path === '/api/review' && req.method === 'GET') return await apiReview(req, env, user);
422:         return json({ error: 'no such endpoint' }, 404);
423:       }
424:       if (path === '/login') return await loginPage(req, env, baseUrl);
425:       if (path === '/auth') return await authRedirect(req, env);
426:       if (path === '/test/session' && req.method === 'POST') return await testSession(req, env);
427:       const m = path.match(/^\/a\/([a-z0-9-]+)\/([a-z0-9-]+)(\/.*)?$/);
428:       if (m) return await proxyApp(req, env, m[1], m[2], m[3] || '', baseUrl);
429:       if (path === '/') return html('<h2>small</h2><p>Deploy a Python app behind a login in one command: <code>npm i -g small-deploy</code></p>');
430:       return html('<p>Not found.</p>', 404);
431:     } catch (err) {
432:       return json({ error: `internal: ${err.message}` }, 500);
433:     }
434:   },
435: 
436:   // 7-day request-log retention. Cutoff formatted with 'T' to match the guard's ISO timestamps.
437:   // ponytail: retention fixed at 7 days — make it a per-app column when someone needs more
438:   async scheduled(_event, env) {
439:     await env.DB.prepare("DELETE FROM request_logs WHERE ts < strftime('%Y-%m-%dT%H:%M:%S', 'now', '-7 days')").run();
440:   },
441: };

sources.packages/cli/bin/small.js:
1: #!/usr/bin/env node
2: 'use strict';
3: const fs = require('fs');
4: const path = require('path');
5: const readline = require('node:readline/promises');
6: const { detect } = require('../lib/detect');
7: const { init } = require('../lib/init');
8: const { write, writeFlyToml } = require('../lib/generate');
9: const { call, apiBase } = require('../lib/api');
10: const { buildBundle } = require('../lib/bundle');
11: const config = require('../lib/config');
12: const envfile = require('../lib/envfile');
13: const fly = require('../lib/fly');
14: 
15: const [cmd, ...rest] = process.argv.slice(2);
16: const flags = { _: [] };
17: for (let i = 0; i < rest.length; i++) {
18:   if (rest[i].startsWith('--')) {
19:     const key = rest[i].slice(2);
20:     flags[key] = rest[i + 1] && !rest[i + 1].startsWith('--') ? rest[++i] : true;
21:   } else {
22:     flags._.push(rest[i]);
23:   }
24: }
25: 
26: async function ask(question) {
27:   const rl = readline.createInterface({ input: process.stdin, output: process.stdout });
28:   const answer = await rl.question(question);
29:   rl.close();
30:   return answer.trim();
31: }
32: 
33: function appName(dir) {
34:   if (flags.app) return flags.app;
35:   return detect(dir).name;
36: }
37: 
38: // ---------- deploy review output ----------
39: 
40: const reviewFmt = {
41:   findings: (x) => `[${x.severity}] ${x.at} — ${x.text}`,
42:   secrets: (x) => `${x.name} ${x.declared ? 'declared' : 'NOT DECLARED'} · used at ${x.used_at}`,
43:   undeclared_secrets: (x) => x,
44:   outbound: (x) => `${x.host} — ${x.purpose} (${x.at})`,
45:   aws: (x) => `${x.action} ${x.resource} (${x.at})`,
46:   shell_exec: (x) => `${x.at} — ${x.command}${x.user_input_reaches_it ? ' · user input reaches it' : ''}`,
47: };
48: 
49: function reviewLine(r) {
50:   const aws = (r.aws || []).length;
51:   const lambdas = (r.aws || []).filter((a) => (a.action || '').startsWith('lambda:')).length;
52:   const awsPart = !aws ? 'no AWS' : lambdas === aws ? `invokes ${aws} Lambda${aws > 1 ? 's' : ''}` : `${aws} AWS call${aws > 1 ? 's' : ''}`;
53:   const hosts = new Set((r.outbound || []).map((o) => o.host)).size;
54:   const outPart = !hosts ? 'no outbound' : `${hosts} outbound host${hosts > 1 ? 's' : ''}`;
55:   const shell = (r.shell_exec || []).length;
56:   const shellPart = !shell ? 'no shell exec' : `${shell} shell exec`;
57:   return `review: ${awsPart} · ${outPart} · ${shellPart} · ${r.risk}`;
58: }
59: 
60: // The review runs concurrently with the Fly build, so it is normally already
61: // stored by the time the deploy finishes; poll briefly for the stamp to change.
62: async function reviewAfterDeploy(name, priorReviewedAt) {
63:   for (let i = 0; i < 6; i++) {
64:     try {
65:       const res = await call('GET', `/api/review?app=${encodeURIComponent(name)}`);
66:       if (res.reviewedAt && res.reviewedAt !== priorReviewedAt) return console.log(reviewLine(res.review));
67:     } catch {}
68:     await new Promise((r) => setTimeout(r, 5000));
69:   }
70:   console.log('review: unavailable');
71: }
72: 
73: function printReport(res) {
74:   const r = res.review;
75:   const section = (title, key) => {
76:     if (!(r[key] || []).length) return;
77:     console.log(`${title}:`);
78:     for (const x of r[key]) console.log(`  ${reviewFmt[key](x)}`);
79:   };
80:   section('findings', 'findings');
81:   section('secrets', 'secrets');
82:   section('undeclared secrets', 'undeclared_secrets');
83:   section('outbound', 'outbound');
84:   section('aws', 'aws');
85:   section('shell exec', 'shell_exec');
86:   const fsys = r.filesystem || { reads: [], writes: [] };
87:   console.log('filesystem:');
88:   console.log(`  reads: ${fsys.reads.join(', ') || '—'}`);
89:   console.log(`  writes: ${fsys.writes.join(', ') || '—'}`);
90:   if ((r.skipped || []).length) console.log(`skipped: ${r.skipped.join(', ')}`);
91:   console.log(`summary: ${r.summary}`);
92:   console.log(`risk: ${r.risk} (${res.model || 'unknown model'}, ${res.reviewedAt})`);
93: }
94: 
95: function printDiff(res) {
96:   if (!res.prev) return console.log('no previous review to diff against');
97:   const { prev, review: cur } = res;
98:   let changed = false;
99:   if (prev.risk !== cur.risk) {
100:     console.log(`risk: ${prev.risk} → ${cur.risk}`);
101:     changed = true;
102:   }
103:   for (const key of Object.keys(reviewFmt)) {
104:     const before = new Set((prev[key] || []).map(reviewFmt[key]));
105:     const after = new Set((cur[key] || []).map(reviewFmt[key]));
106:     for (const s of after) if (!before.has(s)) (changed = true), console.log(`+ ${key.replace('_', ' ')}: ${s}`);
107:     for (const s of before) if (!after.has(s)) (changed = true), console.log(`- ${key.replace('_', ' ')}: ${s}`);
108:   }
109:   for (const dir of ['reads', 'writes']) {
110:     const before = new Set((prev.filesystem || {})[dir] || []);
111:     const after = new Set((cur.filesystem || {})[dir] || []);
112:     for (const s of after) if (!before.has(s)) (changed = true), console.log(`+ filesystem ${dir}: ${s}`);
113:     for (const s of before) if (!after.has(s)) (changed = true), console.log(`- filesystem ${dir}: ${s}`);
114:   }
115:   if (!changed) console.log('no changes since previous deploy');
116: }
117: 
118: const commands = {
119:   async login() {
120:     if (flags.api) config.save({ ...config.load(), apiBase: flags.api });
121:     const email = flags.email || (await ask('work email: '));
122:     const res = await call('POST', '/api/cli/login', { email }, { auth: false });
123:     if (res.devCode) console.log(`(dev) code: ${res.devCode}`);
124:     else console.log(`✓ code sent to ${email}`);
125:     const code = flags.code || (await ask('6-digit code: '));
126:     const v = await call('POST', '/api/cli/verify', { challenge: res.challenge, code }, { auth: false });
127:     config.save({ ...config.load(), token: v.token, email: v.email, org: v.org, apiBase: apiBase() });
128:     console.log(`✓ logged in as ${v.email} (org: ${v.org})`);
129:   },
130: 
131:   async init() {
132:     if (!init(process.cwd(), { force: !!flags.force })) process.exitCode = 1;
133:   },
134: 
135:   async deploy() {
136:     const dir = process.cwd();
137:     if (!fs.existsSync(path.join(dir, 'small.toml')) && !init(dir)) {
138:       process.exitCode = 1;
139:       return;
140:     }
141:     const app = detect(dir, flags);
142:     console.log(`✓ entry: ${app.entry} (${app.framework}) via ${app.via}`);
143: 
144:     const envPath = path.resolve(dir, typeof flags.env === 'string' ? flags.env : '.env');
145:     const secrets = envfile.parse(envPath);
146:     const required = (app.config.secrets && app.config.secrets.required) || [];
147:     const missing = required.filter((k) => !(k in secrets));
148:     if (missing.length) throw new Error(`missing secrets: ${missing.join(', ')} — add them to ${envPath}`);
149: 
150:     write(dir, app);
151:     const review = buildBundle(dir, app.entry, secrets);
152:     const visibility = (app.config.access && app.config.access.visibility) || undefined;
153:     const storage = app.config.storage;
154:     let sizeGb;
155:     if (storage) {
156:       const m = /^(\d+)\s*gb$/i.exec(String(storage.size || '1GB'));
157:       if (!m) throw new Error('storage.size must be whole gigabytes, like "1GB"');
158:       sizeGb = Number(m[1]);
159:     }
160:     const awsRoleArn = (app.config.aws && app.config.aws.role_arn) || undefined;
161:     const kind = app.config.kind === 'job' ? 'job' : 'server';
162:     const d = await call('POST', '/api/deploy', {
163:       name: app.name,
164:       framework: app.framework,
165:       visibility,
166:       awsRoleArn,
167:       kind,
168:       review,
169:       storage: storage ? { sizeGb } : undefined,
170:     });
171:     if (!d.flyToken) throw new Error('control plane has no FLY_API_TOKEN configured');
172:     if (storage && !d.volumeRegion) throw new Error('control plane does not support [storage] yet — redeploy the worker');
173:     writeFlyToml(dir, d.flyApp, app.config.memory, storage ? { path: storage.path || '/data', region: d.volumeRegion } : undefined);
174:     if (storage) console.log(`✓ storage: ${storage.path || '/data'} (${sizeGb}GB volume in ${d.volumeRegion}, survives redeploys)`);
175: 
176:     if (kind === 'job') {
177:       // jobs: build + register the image, start nothing — the control plane starts machines per run
178:       fly.setSecrets(d.flyApp, d.flyToken, secrets);
179:       const image = fly.buildImage(d.flyApp, d.flyToken, dir, `v${Date.now()}`);
180:       await call('POST', '/api/image', { app: app.name, image });
181:       console.log(`✓ built ${app.name} — start it with: small run ${app.name}`);
182:       return;
183:     }
184: 
185:     // gradio builds asset/API URLs from its root; behind the path proxy that must be the public URL
186:     const rootPath = app.framework === 'gradio' ? { GRADIO_ROOT_PATH: d.url.replace(/\/$/, '') } : {};
187:     // [aws] role: guard fetches STS session creds from the control plane at boot
188:     const cpUrl = awsRoleArn ? { SMALL_CP_URL: apiBase() } : {};
189:     // guard batches request-log lines here, authed by the proxy secret it already holds
190:     const logUrl = { SMALL_LOG_URL: `${apiBase()}/api/apps/${app.name}/request-log` };
191:     fly.setSecrets(d.flyApp, d.flyToken, { SMALL_PROXY_SECRET: d.proxySecret, ...rootPath, ...cpUrl, ...logUrl, ...secrets });
192:     if (awsRoleArn) console.log(`✓ aws role: ${awsRoleArn} (STS via control plane)`);
193:     fly.deploy(d.flyApp, d.flyToken, dir);
194: 
195:     console.log(`✓ deployed → ${d.url}`);
196:     const { org } = config.load();
197:     console.log(visibility === 'private' ? '✓ login required · explicit members only' : `✓ login required · anyone @${org}`);
198:     if (d.reviewStarted) await reviewAfterDeploy(app.name, d.reviewedAt);
199:     else console.log('review: unavailable');
200:   },
201: 
202:   async review() {
203:     const name = flags._[0] || appName(process.cwd());
204:     const res = await call('GET', `/api/review?app=${encodeURIComponent(name)}`);
205:     if (!res.review) return console.log('review: unavailable — no reviewed deploy yet');
206:     if (flags.diff) printDiff(res);
207:     else printReport(res);
208:   },
209: 
210:   async run() {
211:     const name = flags._[0] || appName(process.cwd());
212:     const { runId } = await call('POST', '/api/runs', { app: name });
213:     console.log(`run: ${runId}`);
214:     let cursor = -1;
215:     for (;;) {
216:       const r = await call('GET', `/api/runs/${encodeURIComponent(runId)}?after=${cursor}`);
217:       for (const line of r.lines) console.log(line);
218:       if (r.lines.length) cursor = r.cursor;
219:       if (r.status !== 'running' && !r.lines.length) {
220:         console.log(r.exitCode === 0 ? `✓ finished (exit ${r.exitCode})` : `✗ failed (exit ${r.exitCode})`);
221:         process.exitCode = r.exitCode === 0 ? 0 : 1;
222:         return;
223:       }
224:       await new Promise((res) => setTimeout(res, 1000));
225:     }
226:   },
227: 
228:   async runs() {
229:     const name = flags._[0] || appName(process.cwd());
230:     const { runs } = await call('GET', `/api/runs?app=${encodeURIComponent(name)}`);
231:     if (!runs.length) return console.log(`no runs yet — small run ${name}`);
232:     for (const r of runs) {
233:       // sqlite datetime('now') strings are UTC without a zone marker
234:       const dur = r.finished_at ? `${Math.round((new Date(r.finished_at + 'Z') - new Date(r.started_at + 'Z')) / 1000)}s` : '…';
235:       console.log(`${r.run_id}  ${r.status}  ${dur}  ${r.started_by}  ${r.started_at}`);
236:     }
237:   },
238: 
239:   async logs() {
240:     const arg = flags._[0];
241:     if (arg && arg.startsWith('r-')) {
242:       const r = await call('GET', `/api/runs/${encodeURIComponent(arg)}?after=-1`);
243:       for (const line of r.lines) console.log(line);
244:       return;
245:     }
246:     const name = arg || appName(process.cwd());
247:     if (flags.machine) {
248:       const res = await call('GET', `/api/logs?app=${encodeURIComponent(name)}`);
249:       if (!res.flyToken) throw new Error('control plane has no FLY_API_TOKEN configured');
250:       return fly.logs(res.flyApp, res.flyToken);
251:     }
252:     // ponytail: no export — pipe stdout to a file until a --json flag is asked for
253:     let base = `/api/request-logs?app=${encodeURIComponent(name)}`;
254:     if (typeof flags.user === 'string') base += `&user=${encodeURIComponent(flags.user)}`;
255:     if (typeof flags.status === 'string') base += `&status=${encodeURIComponent(flags.status)}`;
256:     const fmt = (l) => {
257:       const t = new Date(l.ts).toTimeString().slice(0, 8);
258:       return `${t} ${l.method} ${l.path} ${l.status} ${l.ms}ms${l.user ? ' ' + l.user : ''}`;
259:     };
260:     const res = await call('GET', base);
261:     if (!flags.follow) {
262:       if (!res.lines.length) return console.log('no requests yet');
263:       for (const l of res.lines) console.log(fmt(l)); // newest first
264:       return;
265:     }
266:     for (const l of [...res.lines].reverse()) console.log(fmt(l)); // --follow reads top-down: oldest of the last 100 first
267:     let cursor = res.cursor;
268:     for (;;) {
269:       await new Promise((r) => setTimeout(r, 1000));
270:       const more = await call('GET', `${base}&after=${cursor}`);
271:       for (const l of more.lines) console.log(fmt(l));
272:       cursor = more.cursor;
273:     }
274:   },
275: 
276:   async share() {
277:     const email = flags._[0];
278:     if (!email || !email.includes('@')) throw new Error('usage: small share <email> [--edit] [--app name]');
279:     const name = appName(process.cwd());
280:     const res = await call('POST', '/api/share', { app: name, email, role: flags.edit ? 'edit' : 'view' });
281:     console.log(`✓ ${res.email} can ${res.role} ${res.app}`);
282:   },
283: 
284:   async list() {
285:     const { apps } = await call('GET', '/api/apps');
286:     if (!apps.length) return console.log('no apps yet — run small deploy');
287:     for (const a of apps) console.log(`${a.name}  ${a.visibility}  owner:${a.owner_email}`);
288:   },
289: 
290: };
291: 
292: const run = commands[cmd];
293: if (!run) {
294:   console.log('usage: small <login|init|deploy|run|runs|share|list|logs|review>');
295:   process.exitCode = 1;
296: } else {
297:   run().catch((err) => {
298:     console.error(`✗ ${err.message}`);
299:     process.exitCode = 1;
300:   });
301: }

