1: // small control plane: CLI API + browser auth wall + router. One Worker + D1.
2: // URLs are path-based (no custom domain): /a/<org>/<app>/... proxies to the app's Fly origin.
3: import { sign, verify, sha256, randomHex } from './token.js';
4: import { ensureFlyApp, ensureVolume, deployTokenFor, startMachine } from './fly.js';
5: import { assumeRole } from './aws.js';
6: import { runReview } from './review.js';
7: 
8: const SESSION_COOKIE = 'small_session';
9: const SESSION_TTL = 7 * 24 * 3600;
10: 
11: const orgOf = (email) => email.split('@')[1].toLowerCase().replace(/\./g, '-');
12: const now = () => Math.floor(Date.now() / 1000);
13: const json = (data, status = 200) => new Response(JSON.stringify(data), { status, headers: { 'Content-Type': 'application/json' } });
14: const html = (body, status = 200, headers = {}) =>
15:   new Response(`<!doctype html><meta name=viewport content="width=device-width,initial-scale=1"><style>body{font-family:system-ui;max-width:26rem;margin:15vh auto;padding:0 1rem}input,button{font-size:1rem;padding:.5rem}</style>${body}`, {
16:     status,
17:     headers: { 'Content-Type': 'text/html;charset=utf-8', ...headers },
18:   });
19: 
20: async function sendEmail(env, to, subject, text) {
21:   if (!env.RESEND_API_KEY) return false; // dev mode: caller falls back to echoing the code/link
22:   const resp = await fetch('https://api.resend.com/emails', {
23:     method: 'POST',
24:     headers: { Authorization: `Bearer ${env.RESEND_API_KEY}`, 'Content-Type': 'application/json' },
25:     body: JSON.stringify({ from: env.EMAIL_FROM || 'small <[REDACTED]>', to: [to], subject, text }),
26:   });
27:   return resp.ok;
28: }
29: 
30: async function cliAuth(req, env) {
31:   const m = (req.headers.get('Authorization') || '').match(/^Bearer (.+)$/);
32:   if (!m) return null;
33:   const p = await verify(m[1], env.MASTER_KEY);
34:   return p && p.t === 'cli' ? p : null;
35: }
36: 
37: async function sessionOf(req, env) {
38:   const header = req.headers.get('X-Small-Session'); // tests use the header; browsers use the cookie
39:   const cookie = (req.headers.get('Cookie') || '').match(new RegExp(`${SESSION_COOKIE}=([^;]+)`));
40:   const p = await verify(header || (cookie && cookie[1]), env.MASTER_KEY);
41:   return p && p.t === 'sess' ? p : null;
42: }
43: 
44: async function appRow(env, org, name) {
45:   return env.DB.prepare('SELECT * FROM apps WHERE org = ? AND name = ?').bind(org, name).first();
46: }
47: 
48: async function canView(env, app, email) {
49:   if (app.owner_email === email) return true;
50:   const member = await env.DB.prepare('SELECT role FROM members WHERE app_id = ? AND email = ?').bind(app.id, email).first();
51:   if (member) return true;
52:   return app.visibility === 'domain' && orgOf(email) === app.org;
53: }
54: 
55: async function canEdit(env, app, email) {
56:   if (app.owner_email === email) return true;
57:   const member = await env.DB.prepare('SELECT role FROM members WHERE app_id = ? AND email = ?').bind(app.id, email).first();
58:   return member && member.role === 'edit';
59: }
60: 
61: // ---------- CLI API ----------
62: 
63: async function apiLogin(req, env) {
64:   const { email } = await req.json();
65:   if (!email || !email.includes('@')) return json({ error: 'valid email required' }, 400);
66:   const code = String(crypto.getRandomValues(new Uint32Array(1))[0] % 1000000).padStart(6, '0');
67:   const challenge = await sign({ t: 'challenge', email, codeHash: await sha256(code), exp: now() + 600 }, env.MASTER_KEY);
68:   const sent = await sendEmail(env, email, `small login code: ${code}`, `Your small login code is ${code}\nIt expires in 10 minutes.`);
69:   if (sent) return json({ challenge });
70:   // Echoing the code is an auth bypass — only allowed on test/dev instances (marked by TEST_BYPASS_SECRET).
71:   if (!env.TEST_BYPASS_SECRET) return json({ error: 'email not configured on this control plane' }, 503);
72:   return json({ challenge, devCode: code, warning: 'test instance — code echoed' });
73: }
