75: async function apiVerify(req, env) {
76:   const { challenge, code } = await req.json();
77:   const p = await verify(challenge, env.MASTER_KEY);
78:   if (!p || p.t !== 'challenge' || p.codeHash !== (await sha256(String(code)))) return json({ error: 'bad or expired code' }, 401);
79:   // ponytail: CLI tokens never expire; revoke by rotating MASTER_KEY. Add exp + refresh when it matters.
80:   const token = await sign({ t: 'cli', email: p.email, org: orgOf(p.email) }, env.MASTER_KEY);
81:   return json({ token, email: p.email, org: orgOf(p.email) });
82: }
