178:   await env.DB.batch(
179:     lines.slice(0, 500).map((l) =>
180:       stmt.bind(app.org, app.name, String(l.ts || ''), String(l.method || ''), String(l.path || ''), Number(l.status) || 0, Number(l.ms) || 0, l.user == null ? null : String(l.user))
