186: // ponytail: no log search — user/status filters only, add a path/text query param when asked
187: async function apiRequestLogs(req, env, user) {
188:   const url = new URL(req.url);
189:   const name = url.searchParams.get('app');
190:   const app = await appRow(env, user.org, name);
191:   if (!app) return json({ error: `no app named ${name}` }, 404);
192:   if (!(await canView(env, app, user.email))) return json({ error: 'no access' }, 403);
193:   const where = ['org = ?', 'slug = ?'];
194:   const binds = [app.org, app.name];
195:   const byUser = url.searchParams.get('user');
196:   if (byUser) { where.push('user = ?'); binds.push(byUser); }
197:   const byStatus = url.searchParams.get('status') || '';
198:   if (/^[1-5]xx$/.test(byStatus)) { where.push('status BETWEEN ? AND ?'); binds.push(+byStatus[0] * 100, +byStatus[0] * 100 + 99); }
199:   else if (/^\d+$/.test(byStatus)) { where.push('status = ?'); binds.push(+byStatus); }
200:   const after = url.searchParams.get('after');
201:   const order = after === null ? 'ORDER BY id DESC LIMIT 100' : 'ORDER BY id LIMIT 1000'; // no cursor: last 100 newest-first; cursor: ascending for --follow
202:   if (after !== null) { where.push('id > ?'); binds.push(+after); }
203:   const { results } = await env.DB.prepare(`SELECT id, ts, method, path, status, ms, user FROM request_logs WHERE ${where.join(' AND ')} ${order}`).bind(...binds).all();
204:   const cursor = results.length ? Math.max(results[0].id, results[results.length - 1].id) : +(after || 0);
205:   return json({ lines: results, cursor });
206: }
