171: async function apiRequestLogIngest(req, env, slug) {
172:   const m = (req.headers.get('Authorization') || '').match(/^Bearer (.+)$/);
173:   const app = m && (await env.DB.prepare('SELECT * FROM apps WHERE proxy_secret = ?').bind(m[1]).first());
174:   if (!app || app.name !== slug) return json({ error: 'forbidden' }, 403);
175:   const { lines = [] } = await req.json();
176:   if (!Array.isArray(lines) || !lines.length) return json({ ok: true });
177:   const stmt = env.DB.prepare('INSERT INTO request_logs (org, slug, ts, method, path, status, ms, user) VALUES (?, ?, ?, ?, ?, ?, ?, ?)');
178:   await env.DB.batch(
179:     lines.slice(0, 500).map((l) =>
180:       stmt.bind(app.org, app.name, String(l.ts || ''), String(l.method || ''), String(l.path || ''), Number(l.status) || 0, Number(l.ms) || 0, l.user == null ? null : String(l.user))
