293: // Called by runner.py with the per-run token — not a CLI token.
294: async function apiRunLog(req, env, runId) {
295:   const m = (req.headers.get('Authorization') || '').match(/^Bearer (.+)$/);
296:   const p = m && (await verify(m[1], env.MASTER_KEY));
297:   if (!p || p.t !== 'run' || p.run !== runId) return json({ error: 'bad run token' }, 401);
298:   const { lines = [], exitCode } = await req.json();
299:   if (lines.length) {
300:     // ponytail: MAX(seq) is race-free only because one runner posts batches sequentially
301:     const { m: maxSeq } = await env.DB.prepare('SELECT COALESCE(MAX(seq), -1) AS m FROM run_logs WHERE run_id = ?').bind(runId).first();
302:     let seq = maxSeq;
303:     const stmt = env.DB.prepare('INSERT INTO run_logs (run_id, seq, line) VALUES (?, ?, ?)');
304:     await env.DB.batch(lines.map((l) => stmt.bind(runId, ++seq, String(l))));
305:   }
306:   if (exitCode !== undefined && exitCode !== null) {
307:     await env.DB.prepare("UPDATE runs SET status = ?, exit_code = ?, finished_at = datetime('now') WHERE run_id = ?")
308:       .bind(exitCode === 0 ? 'finished' : 'failed', exitCode, runId)
309:       .run();
310:   }
311:   return json({ ok: true });
312: }
