60: // The review runs concurrently with the Fly build, so it is normally already
61: // stored by the time the deploy finishes; poll briefly for the stamp to change.
62: async function reviewAfterDeploy(name, priorReviewedAt) {
63:   for (let i = 0; i < 6; i++) {
64:     try {
65:       const res = await call('GET', `/api/review?app=${encodeURIComponent(name)}`);
66:       if (res.reviewedAt && res.reviewedAt !== priorReviewedAt) return console.log(reviewLine(res.review));
67:     } catch {}
68:     await new Promise((r) => setTimeout(r, 5000));
69:   }
70:   console.log('review: unavailable');
71: }
72: 
73: function printReport(res) {
74:   const r = res.review;
75:   const section = (title, key) => {
76:     if (!(r[key] || []).length) return;
77:     console.log(`${title}:`);
78:     for (const x of r[key]) console.log(`  ${reviewFmt[key](x)}`);
79:   };
80:   section('findings', 'findings');
81:   section('secrets', 'secrets');
82:   section('undeclared secrets', 'undeclared_secrets');
83:   section('outbound', 'outbound');
84:   section('aws', 'aws');
85:   section('shell exec', 'shell_exec');
86:   const fsys = r.filesystem || { reads: [], writes: [] };
87:   console.log('filesystem:');
88:   console.log(`  reads: ${fsys.reads.join(', ') || '—'}`);
89:   console.log(`  writes: ${fsys.writes.join(', ') || '—'}`);
90:   if ((r.skipped || []).length) console.log(`skipped: ${r.skipped.join(', ')}`);
91:   console.log(`summary: ${r.summary}`);
92:   console.log(`risk: ${r.risk} (${res.model || 'unknown model'}, ${res.reviewedAt})`);
93: }
94: 
95: function printDiff(res) {
96:   if (!res.prev) return console.log('no previous review to diff against');
97:   const { prev, review: cur } = res;
98:   let changed = false;
99:   if (prev.risk !== cur.risk) {
100:     console.log(`risk: ${prev.risk} → ${cur.risk}`);
101:     changed = true;
102:   }
103:   for (const key of Object.keys(reviewFmt)) {
104:     const before = new Set((prev[key] || []).map(reviewFmt[key]));
105:     const after = new Set((cur[key] || []).map(reviewFmt[key]));
106:     for (const s of after) if (!before.has(s)) (changed = true), console.log(`+ ${key.replace('_', ' ')}: ${s}`);
107:     for (const s of before) if (!after.has(s)) (changed = true), console.log(`- ${key.replace('_', ' ')}: ${s}`);
108:   }
109:   for (const dir of ['reads', 'writes']) {
110:     const before = new Set((prev.filesystem || {})[dir] || []);
111:     const after = new Set((cur.filesystem || {})[dir] || []);
112:     for (const s of after) if (!before.has(s)) (changed = true), console.log(`+ filesystem ${dir}: ${s}`);
113:     for (const s of before) if (!after.has(s)) (changed = true), console.log(`- filesystem ${dir}: ${s}`);
114:   }
115:   if (!changed) console.log('no changes since previous deploy');
116: }
